body{margin:0}
.op{font-family:"DM Sans",ui-sans-serif,system-ui,sans-serif;color:var(--text);background:var(--bg)}
.t-dark{--bg:#08080c;--panel:#0e0e14;--card:#141420;--raised:#1a1a2a;--line:#222236;--line3:#383f4a;--text:#f4f4fa;--head:#e8e8f0;--body:#9999b8;--muted:#a4adbc;--dim:#7f8894;--accent:#5eead4;--accent-soft:#153a32;--danger:#f87171;--warn:#e7b85c;--info:#78aef8;--ty-spec:#c084fc;--ty-us:#60a5fa;--ty-t:#22d3ee;--ty-bl:#fbbf24}
