.mono{font-family:"Source Code Pro",ui-monospace,monospace}
.h{font-family:Outfit,ui-sans-serif,system-ui,sans-serif}
.eyebrow{font-family:"Source Code Pro",monospace;font-size:12px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:var(--accent)}
.tag{display:inline-flex;align-items:center;height:22px;padding:0 7px;border-radius:6px;font-family:"Source Code Pro",monospace;font-size:12px;font-weight:600;color:var(--c);background:color-mix(in srgb,var(--c) 14%,transparent);white-space:nowrap}
.spec{--c:var(--ty-spec)}.us{--c:var(--ty-us)}.tk{--c:var(--ty-t)}.bl{--c:var(--ty-bl)}
.g{width:10px;height:10px;box-sizing:border-box;display:inline-block;flex:none}
.g-out{border:2px solid var(--info);border-radius:50%}
.g-done{border-radius:50%;background:var(--dim)}
svg.i{fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;flex:none}
.irail{flex:0 0 64px;box-sizing:border-box;padding:16px 10px;display:flex;flex-direction:column;align-items:center;gap:6px;border-right:1px solid var(--line);background:var(--panel)}
.irail a{display:flex;align-items:center;justify-content:center;width:44px;height:44px;border-radius:10px;color:var(--muted)}
.irail a[aria-current="page"]{background:var(--accent-soft);color:var(--accent)}
.top{display:flex;flex-wrap:wrap;align-items:center;gap:12px;min-height:60px;padding:0 32px;border-bottom:1px solid var(--line)}
.crumb{font-size:13px;color:var(--dim)}.crumb b{color:var(--text);font-weight:600}
.pill{display:inline-flex;align-items:center;gap:8px;height:28px;padding:0 10px;border-radius:999px;border:1px solid var(--line);font-size:12px;color:var(--muted);white-space:nowrap}
.dot{width:7px;height:7px;border-radius:50%;background:var(--accent);box-shadow:0 0 8px var(--accent)}
.chip{display:inline-flex;align-items:center;gap:6px;height:32px;padding:0 12px;border-radius:999px;border:1px solid var(--line3);font-size:13px;color:var(--muted);background:var(--card)}
.chip.on{border-color:var(--accent);color:var(--text);background:var(--accent-soft)}
.day{display:grid;grid-template-columns:150px minmax(0,1fr);gap:24px;padding:22px 0;border-top:1px solid var(--line)}
.day .d{display:flex;flex-direction:column;gap:4px}
.day .d b{font-family:Outfit,sans-serif;font-size:18px;font-weight:600}
.day .d span{font-size:13px;color:var(--dim)}
.ev{display:flex;flex-direction:column;gap:8px;padding:14px 16px;border-radius:12px;border:1px solid var(--line);background:var(--panel)}
.ev .hd{display:flex;flex-wrap:wrap;gap:8px;align-items:center;font-size:13px;color:var(--dim)}
.ev .tt{font-size:14.5px;font-weight:500;color:var(--head)}
.kids{display:flex;flex-wrap:wrap;gap:6px}
.line{display:flex;gap:10px;align-items:center;font-size:13.5px;color:var(--head);min-height:30px}
.line .t{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.verb{font-family:"Source Code Pro",monospace;font-size:12px;font-weight:600;padding:1px 6px;border-radius:4px}
.v-new{color:var(--accent);background:var(--accent-soft)}
.v-done{color:var(--dim);background:var(--raised)}
.pf{font-family:"Source Code Pro",monospace;font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--accent);border:1px dashed var(--accent);border-radius:4px;padding:1px 5px}

